-- Etapa 6C. Compra 2017; UF do pedido SP; todos os status. Executar READ ONLY.
WITH p AS (SELECT x.*,c.dia,c.mes FROM gold.fato_pedidos x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP'),i AS (SELECT x.*,c.dia,c.mes FROM gold.fato_itens_pedido x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP'),g AS (SELECT x.*,c.dia,c.mes FROM gold.fato_pagamentos x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP') SELECT 'fato_itens_pedido' fato,(SELECT count(*) FROM i x LEFT JOIN gold.fato_pedidos z USING(order_id) WHERE z.order_id IS NULL OR (x.cliente_sk,x.localizacao_sk,x.data_compra_sk,x.order_status,x.order_purchase_timestamp) IS DISTINCT FROM (z.cliente_sk,z.localizacao_sk,z.data_compra_sk,z.order_status,z.order_purchase_timestamp)) contexto_divergente,(SELECT count(*) FROM ((SELECT order_id FROM i) EXCEPT (SELECT x.order_id FROM gold.fato_itens_pedido x JOIN p USING(order_id))) a) fora_escopo,(SELECT count(*) FROM ((SELECT x.order_id FROM gold.fato_itens_pedido x JOIN p USING(order_id)) EXCEPT (SELECT order_id FROM i)) a) faltando_escopo UNION ALL SELECT 'fato_pagamentos' fato,(SELECT count(*) FROM g x LEFT JOIN gold.fato_pedidos z USING(order_id) WHERE z.order_id IS NULL OR (x.cliente_sk,x.localizacao_sk,x.data_compra_sk,x.order_status,x.order_purchase_timestamp) IS DISTINCT FROM (z.cliente_sk,z.localizacao_sk,z.data_compra_sk,z.order_status,z.order_purchase_timestamp)) contexto_divergente,(SELECT count(*) FROM ((SELECT order_id FROM g) EXCEPT (SELECT x.order_id FROM gold.fato_pagamentos x JOIN p USING(order_id))) a) fora_escopo,(SELECT count(*) FROM ((SELECT x.order_id FROM gold.fato_pagamentos x JOIN p USING(order_id)) EXCEPT (SELECT order_id FROM g)) a) faltando_escopo;
